-- Additive migration, applied as Supabase 20261101095746. Legacy rows retained.
CREATE TABLE public.assessment_windows (start_year integer PRIMARY KEY CHECK(start_year BETWEEN 2000 AND 2100),active_period public."AssessmentPeriod",revision integer NOT NULL DEFAULT 1,activated_by integer REFERENCES public.users(id) ON DELETE SET NULL,updated_at timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE public.assessment_library_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),period public."AssessmentPeriod" NOT NULL,version integer NOT NULL,rows jsonb NOT NULL CHECK(jsonb_typeof(rows)='array'),published_by integer REFERENCES public.users(id) ON DELETE SET NULL,created_at timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(period,version));
CREATE TABLE public.assessment_library_heads(period public."AssessmentPeriod" PRIMARY KEY,revision_id uuid NOT NULL REFERENCES public.assessment_library_revisions(id) ON DELETE RESTRICT);
ALTER TABLE public.host_sessions ADD COLUMN catalog_revision_id uuid REFERENCES public.assessment_library_revisions(id) ON DELETE RESTRICT;
CREATE TABLE public.coordinator_change_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),teacher_id integer NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,request_key varchar(120) NOT NULL,action varchar(40) NOT NULL,encrypted_payload text NOT NULL,status varchar(20) NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected')),result jsonb,reviewed_by integer REFERENCES public.users(id) ON DELETE SET NULL,created_at timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(teacher_id,request_key));
CREATE INDEX coordinator_requests_pending_idx ON public.coordinator_change_requests(status,created_at);
INSERT INTO public.assessment_windows(start_year) SELECT DISTINCT start_year FROM public.school_years ON CONFLICT DO NOTHING;
INSERT INTO public.assessment_library_revisions(period,version,rows) SELECT c.assessment_period,1,jsonb_agg(jsonb_build_object('id',c.id,'assessmentPeriod',c.assessment_period,'category',c.category,'position',c.position,'content',c.content,'storyTitle',c.story_title) ORDER BY c.category,c.position) FROM public.assessment_content c JOIN (SELECT assessment_period,min(teacher_id) owner FROM public.assessment_content GROUP BY assessment_period)o ON o.assessment_period=c.assessment_period AND o.owner=c.teacher_id GROUP BY c.assessment_period;
INSERT INTO public.assessment_library_heads SELECT period,id FROM public.assessment_library_revisions;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['assessment_windows','assessment_library_revisions','assessment_library_heads','coordinator_change_requests'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC, anon, authenticated',t);END LOOP;END $$;
